mapper.select:
SELECT umb.id AS boxItemId, umb.drug_id AS drugId, COALESCE(db.common_name, db.generic_name, CASE WHEN INSTR(umb.note, '{AI药品:') > 0 THEN SUBSTRING(umb.note, LOCATE('{AI药品:', umb.note) + 6, LOCATE('}', umb.note) - LOCATE('{AI药品:', umb.note) - 6) ELSE NULL END) AS drugName, db.generic_name AS genericName, db.trade_name AS tradeName, db.common_name AS commonName, db.specification AS specification, umb.dosage, umb.frequency, DATE_FORMAT(umb.start_date, '%Y-%m-%d') AS startDate, DATE_FORMAT(umb.end_date, '%Y-%m-%d') AS endDate, DATE_FORMAT(umb.expiry_date, '%Y-%m-%d') AS expiryDate, umb.total_quantity AS totalQuantity, umb.remaining_quantity AS remainingQuantity, umb.note, CASE WHEN INSTR(umb.note, '{AI药品:') > 0 THEN SUBSTRING(umb.note, LOCATE('{AI药品:', umb.note) + 6, LOCATE('}', umb.note) - LOCATE('{AI药品:', umb.note) - 6) ELSE NULL END AS aiDrugName, umb.status, DATE_FORMAT(umb.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM user_medicine_box umb LEFT JOIN drug_base db ON umb.drug_id = db.id WHERE umb.user_id = #{userId}
AND umb.status = #{status}
ORDER BY umb.created_at DESC

SELECT umb.id AS boxItemId, umb.drug_id AS drugId, COALESCE(db.common_name, db.generic_name, CASE WHEN INSTR(umb.note, '{AI药品:') > 0 THEN SUBSTRING(umb.note, LOCATE('{AI药品:', umb.note) + 6, LOCATE('}', umb.note) - LOCATE('{AI药品:', umb.note) - 6) ELSE NULL END) AS drugName, db.generic_name AS genericName, db.trade_name AS tradeName, db.common_name AS commonName, db.specification AS specification, umb.dosage, umb.frequency, DATE_FORMAT(umb.start_date, '%Y-%m-%d') AS startDate, DATE_FORMAT(umb.end_date, '%Y-%m-%d') AS endDate, DATE_FORMAT(umb.expiry_date, '%Y-%m-%d') AS expiryDate, umb.total_quantity AS totalQuantity, umb.remaining_quantity AS remainingQuantity, umb.note, CASE WHEN INSTR(umb.note, '{AI药品:') > 0 THEN SUBSTRING(umb.note, LOCATE('{AI药品:', umb.note) + 6, LOCATE('}', umb.note) - LOCATE('{AI药品:', umb.note) - 6) ELSE NULL END AS aiDrugName, umb.status, DATE_FORMAT(umb.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM user_medicine_box umb LEFT JOIN drug_base db ON umb.drug_id = db.id WHERE umb.user_id = #{userId}
AND umb.status = #{status}
AND ( db.generic_name LIKE CONCAT('%', #{keyword}, '%') OR db.specification LIKE CONCAT('%', #{keyword}, '%') OR umb.dosage LIKE CONCAT('%', #{keyword}, '%') OR umb.note LIKE CONCAT('%', #{keyword}, '%') OR (INSTR(umb.note, '{AI药品:') > 0 AND SUBSTRING(umb.note, LOCATE('{AI药品:', umb.note) + 6, LOCATE('}', umb.note) - LOCATE('{AI药品:', umb.note) - 6) LIKE CONCAT('%', #{keyword}, '%')) )
ORDER BY umb.created_at DESC
